    internal static int FtPath(emon.Port.Cells pa, int page, int kind, int x0, int y0, int x1, int y1, int fill, int stroke, int flags) {
        // A row of `paths` (stride 24): kind 1 line, 2 rect, 3 curve, 4 other; flags 8 filled, 16 stroked, 1 closed, 64 pattern.
        int k = 0;
        emon.Port.CellsPush(pa, page);
        emon.Port.CellsPush(pa, kind);
        emon.Port.CellsPush(pa, x0);
        emon.Port.CellsPush(pa, y0);
        emon.Port.CellsPush(pa, x1);
        emon.Port.CellsPush(pa, y1);
        emon.Port.CellsPush(pa, fill);
        emon.Port.CellsPush(pa, stroke);
        emon.Port.CellsPush(pa, 75);
        emon.Port.CellsPush(pa, 1000);
        emon.Port.CellsPush(pa, 1000);
        emon.Port.CellsPush(pa, flags);
        k = 12;
        while (k < 24) {
            emon.Port.CellsPush(pa, 0);
            k += 1;
        }
        return 0;
    }
