    internal static int FtKind(emon.Port.Cells pa, emon.Port.Cells fw, emon.Port.Cells fl, emon.Port.Cells et, emon.Port.Cells ws, int x0, int y0, int x1, int y1, int pageh) {
        // Measure the region of page 1 and answer the packed kind and confidence (kind * 1024 + confidence); 0 when it is no figure.
        emon.Port.Cells grl = emon.Port.NewCells();
