    [Xunit.Fact]
    public static void TestAxesWithTicksAndBarsAreAChart() {
        emon.Port.Cells pa = emon.Port.NewCells();
        emon.Port.Cells fw = emon.Port.NewCells();
        emon.Port.Cells fl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells ws = emon.Port.NewCells();
        int pk = 0;
        // the vertical axis, the horizontal axis, three ticks on the vertical, three bars on one baseline of different heights
        FtPath(pa, 1, 1, 10162, 15712, 10238, 28538, -1, 0, 16);
        FtPath(pa, 1, 1, 10162, 28462, 37988, 28538, -1, 0, 16);
        FtPath(pa, 1, 1, 9862, 28462, 10238, 28538, -1, 0, 16);
        FtPath(pa, 1, 1, 9862, 22000, 10238, 22076, -1, 0, 16);
        FtPath(pa, 1, 1, 9862, 16000, 10238, 16076, -1, 0, 16);
        FtPath(pa, 1, 2, 10800, 21750, 16313, 28500, 3894949, -1, 8);
        FtPath(pa, 1, 2, 17363, 18375, 22875, 28500, 3894949, -1, 8);
        FtPath(pa, 1, 2, 23925, 20063, 29438, 28500, 3894949, -1, 8);
        pk = FtKind(pa, fw, fl, et, ws, 9800, 15700, 38000, 28600, 79200);
        emon.Testport.AssertEq(emon.Port.CellsAt(ws, 3), 1, "the two long rules meet: axes");
        emon.Testport.AssertThat(emon.Port.CellsAt(ws, 4) >= 3, "three short rules across the axis: ticks");
        emon.Testport.AssertEq(emon.Port.CellsAt(ws, 5), 3, "three bars on one baseline");
        emon.Testport.AssertEq(pk / 1024, Model.FgChart(), "a chart");
        emon.Testport.AssertThat((pk % 1024) >= 700, "and a sure one: axes, ticks and bars");
    }
