        emon.Testport.AssertThat((Figclass.FcImageKind(fi, 0, 20000, 15000, 20000, 35000, 79200, 0) % 1024) >= 600, "a sure one");
        FtFi(fi, 1, 0, 2, 3, 8, 60, 0);
