        emon.Testport.AssertThat((Figclass.FcImageKind(fi, 0, 30000, 20000, 20000, 40000, 79200, 0) % 1024) < 500, "which is not sure enough for a figure with no caption");
        emon.Testport.AssertEq(Figclass.FcImageKind(fi, 0, 4000, 4000, 5000, 9000, 79200, 0) / 1024, Model.FgLogo(), "a small flat one at the head of the page");
        emon.Testport.AssertEq(Figclass.FcImageKind(fi, 0, 4000, 4000, 30000, 34000, 79200, 0) / 1024, Model.FgUnknown(), "and in the middle of it");
        FtFi(fi, 1, 9, 1, 1, 1, 20, 0);
