    internal static int FtPara(emon.Port.Cells nodes, emon.Port.Cells regions, emon.Port.Cells text, int kind, int nch, int x0, int y0, int x1, int y1) {
        // A node of `kind` with `nch` letters of text and one region on page 1.
        int n = Model.NodeNew(nodes, kind, 0);
        int at = emon.Port.CellsLen(text);
        int i = 0;
        while (i < nch) {
            Model.TextAppendCp(text, 97);
            i += 1;
        }
        Model.NodeSetText(nodes, n, at, nch);
        Model.NodeAddRegion(nodes, regions, n, 1, x0, y0, x1, y1);
        return n;
    }
    [Xunit.Fact]
    public static void TestAShortParagraphOnAFigureIsItsLabelAndALongOneStays() {
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells nn = emon.Port.NewCells();
        emon.Port.Cells na = emon.Port.NewCells();
        emon.Port.Cells nr = emon.Port.NewCells();
        emon.Port.Cells nm = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        emon.Port.Cells fg = emon.Port.NewCells();
        emon.Port.Cells fd = emon.Port.NewCells();
        emon.Port.Cells ab = emon.Port.NewCells();
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Model.PageNew(pages, 1, 61200, 79200, 0, Model.PkVector());
        FtPara(nodes, regions, text, Model.NkParagraph(), 3, 8000, 12000, 9600, 12750);
        FtPara(nodes, regions, text, Model.NkParagraph(), 60, 7200, 50000, 54000, 51250);
        FtPara(nodes, regions, text, Model.NkParagraph(), 4, 15000, 31000, 17000, 31750);
        FtCand(cand, 1, 10000, 10000, 40000, 30000);
        FtFd(fd, Model.FgChart(), 760);
        emon.Port.CellsPush(fg, 0);
        emon.Port.CellsPush(fg, 0);
        Restruct.RsFigures(nodes, attrs, regions, text, nn, na, nr, nm, cand, fg, fd, ab);
        emon.Testport.AssertEq(Model.NodeCount(nn), 3, "the document, the figure and the long paragraph: the two short ones are labels");
        emon.Testport.AssertEq(Model.NodeKind(nn, 1), Model.NkFigure(), "the figure goes in by its top edge (30000 is above the paragraph at 50000)");
        emon.Testport.AssertEq(Model.NodeSub(nn, 1), Model.FgChart(), "its kind");
        emon.Testport.AssertEq(Model.NodeConf(nn, 1), 760, "its confidence");
        emon.Testport.AssertThat(Model.NodeAttr(nn, na, 1, Model.FkLabels()) >= 0, "it has labels");
        emon.Testport.AssertEq(Model.NodeKind(nn, 2), Model.NkParagraph(), "the long paragraph is still body text");
    }
    [Xunit.Fact]
    public static void TestAFigureGoesInBeforeItsCaptionWhateverItsTopEdgeSays() {
        emon.Port.Cells nodes = emon.Port.NewCells();
        emon.Port.Cells attrs = emon.Port.NewCells();
        emon.Port.Cells regions = emon.Port.NewCells();
        emon.Port.Cells text = emon.Port.NewCells();
        emon.Port.Cells pages = emon.Port.NewCells();
        emon.Port.Cells ledger = emon.Port.NewCells();
        emon.Port.Cells layout = emon.Port.NewCells();
        emon.Port.Cells nn = emon.Port.NewCells();
        emon.Port.Cells na = emon.Port.NewCells();
        emon.Port.Cells nr = emon.Port.NewCells();
        emon.Port.Cells nm = emon.Port.NewCells();
        emon.Port.Cells cand = emon.Port.NewCells();
        emon.Port.Cells fg = emon.Port.NewCells();
        emon.Port.Cells fd = emon.Port.NewCells();
        emon.Port.Cells ab = emon.Port.NewCells();
        int c = 0;
        Model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout);
        Model.PageNew(pages, 1, 61200, 79200, 0, Model.PkVector());
        // document > paragraph (top), paragraph (far below: the other column), caption (just under the figure)
        FtPara(nodes, regions, text, Model.NkParagraph(), 60, 7200, 5000, 54000, 6250);
        FtPara(nodes, regions, text, Model.NkParagraph(), 60, 7200, 40000, 54000, 41250);
        c = FtPara(nodes, regions, text, Model.NkCaption(), 20, 10000, 31000, 30000, 32000);
        Model.NodeSetAux(nodes, c, 1);
        FtCand(cand, 1, 10000, 10000, 30000, 30000);
        FtFd(fd, Model.FgChart(), 760);
        emon.Port.CellsPush(fg, 0);
        emon.Port.CellsPush(fg, 0);
        Restruct.RsFigures(nodes, attrs, regions, text, nn, na, nr, nm, cand, fg, fd, ab);
        emon.Testport.AssertEq(Model.NodeCount(nn), 5, "the document, three blocks and the figure");
        emon.Testport.AssertEq(Model.NodeKind(nn, 3), Model.NkFigure(), "the figure is just before its caption, after the paragraph that is lower on the page");
        emon.Testport.AssertEq(Model.NodeKind(nn, 4), Model.NkCaption(), "and the caption follows it");
    }
